 *  dated): a grade with no rate in force on a date takes the parent's, then its parent's, up to three levels up.
 *  `fiscalStartMonth` is the month (1 to 12; 1 unless set; not dated) the sheet's fiscal year starts in.
 *  `alertThreshold` is the sheet's alert threshold (two decimals; null when blank: off; not dated): a person whose
 *  due-total goes from at or below it to above it is written an ALERT line. `escalateAfter` is the sheet's escalation
 *  gap in days (null when blank: off; not dated): reminding a claim whose previous reminder was at least that many days
 *  before the sheet's today escalates it, once per claim ever. `reviewSla` is the sheet's review SLA in days (null when
 *  blank: none; not dated): a REVIEW claim whose review day plus it is before the sheet's today is review-late. */
export type Settings = { clerkLimit: string | null; floor: string; terms: number; latePct: string; roles: Role[]; policyDate: string | null; periodNumberingFrom: string | null;
  gradeTerms: Record<string, number>; cap: string | null; dated: Record<string, DatedValue[]>;
  permissions: Record<string, string>; graceDays: number | null; delegations: Delegation[];
  entryDate: string | null; holidays: string[]; voidReasons: string[]; pot: string | null;
  parent: string | null; fiscalStartMonth: number; alertThreshold: string | null; escalateAfter: number | null; reviewSla: number | null };

/** A steward's (`by`) delegation of the steward role to a user, from a date to a date (yyyy-mm-dd, inclusive):
 *  while the sheet's today is inside it the user acts as a steward. */
export type Delegation = { user: string; by: string; from: string; to: string };
  const [permissions, setPermissions] = useState<Record<string, string>>({});
  const [graceDays, setGraceDays] = useState<string | null>(null);
  const [escalateAfter, setEscalateAfter] = useState<string | null>(null);
  const [reviewSla, setReviewSla] = useState<string | null>(null);
  const [entryDate, setEntryDate] = useState<string | null>(null);
  const [pot, setPot] = useState<string | null>(null);
  const [parent, setParent] = useState<string | null>(null);
  const [fiscalStartMonth, setFiscalStartMonth] = useState<string | null>(null);
  const [alertThreshold, setAlertThreshold] = useState<string | null>(null);
  const [rounding, setRounding] = useState<string | null>(null);
  const today = useSheetToday(sheetId).data?.today;
  const [user, setUser] = useState('');
  const [role, setRole] = useState('');

  const [delegateUser, setDelegateUser] = useState('');
  const [delegateFrom, setDelegateFrom] = useState('');
  const [delegateTo, setDelegateTo] = useState('');

  const [holidayDate, setHolidayDate] = useState('');
  const [voidReason, setVoidReason] = useState('');

  const saveOnce = useSingleFlight();
  const save = useMutation({
    mutationFn: (f: { clerkLimit: string | null; floor: string | null; terms: string | null; latePct: string | null; policyDate: string | null; periodNumberingFrom: string | null; gradeTerms: Record<string, string>; cap: string | null; from: Record<string, string>; proofThreshold: string | null; noteThreshold: string | null; permissions: Record<string, string>; graceDays: string | null; entryDate: string | null; gradeGrace: Record<string, string>; gradeProofThreshold: Record<string, string>; pot: string | null; parent: string | null; fiscalStartMonth: string | null; alertThreshold: string | null; rounding: string | null; reviewThreshold: string | null; escalateAfter: string | null; reviewSla: string | null }) =>
      postJson<Settings>(`/api/sheets/${encodeURIComponent(sheetId)}/settings`, f),
    onSuccess: (saved) => {
      setLimit(null);
      setFloor(null);
      setTerms(null);
      setGradeTerms({});
      setGradeGrace({});
      setGradeProof({});
      setLatePct(null);
      setPolicyDate(null);
      setNumberingFrom(null);
      setCap(null);
      setProofThreshold(null);
      setNoteThreshold(null);
      setReviewThreshold(null);
      setFrom({});
      setPermissions({});
      setGraceDays(null);
      setEscalateAfter(null);
      setReviewSla(null);
      setEntryDate(null);
      setPot(null);
      setParent(null);
      setFiscalStartMonth(null);
      setAlertThreshold(null);
      setRounding(null);
      <p>
        Parent sheet: <strong data-testid="sheet-parent">{settings.data?.parent ?? ''}</strong>
      </p>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          saveOnce(() => {
            save.reset();
            return save.mutateAsync({ clerkLimit: limit, floor, terms, latePct, policyDate, periodNumberingFrom: numberingFrom, gradeTerms, cap, from, proofThreshold, noteThreshold, permissions, graceDays, entryDate, gradeGrace, gradeProofThreshold: gradeProof, pot, parent, fiscalStartMonth, alertThreshold, rounding, reviewThreshold, escalateAfter, reviewSla });
          });
        }}
      >
        <label>
          Clerk limit{' '}
          <input
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Review SLA (days){' '}
          <input
            data-testid="setting-review-sla"
            inputMode="numeric"
            value={reviewSla ?? ''}
            onFocus={() => setReviewSla((v) => v ?? '')}
            onChange={(e) => {
              setReviewSla(e.target.value);
              save.reset();
            }}
          />
        </label>{' '}
        <label>
          Entry date{' '}
          <input
            data-testid="setting-entry-date"
            placeholder="yyyy-mm-dd"
            value={entryDate ?? ''}
            onFocus={() => setEntryDate((v) => v ?? '')}
            onChange={(e) => {
              setEntryDate(e.target.value);
        , rounding <strong data-testid="setting-rounding-current">{fig(settingOn(settings.data, 'rounding', today) ?? '')}</strong>
        {PERM_ACTIONS.map((a) => (
          <span key={a}>
            , may {a} <strong data-testid={`setting-perm-${a}-current`}>{fig(settings.data?.permissions?.[a] ?? '')}</strong>
          </span>
        ))}
        , grace days <strong data-testid="setting-grace-days-current">{fig(settings.data?.graceDays ?? '')}</strong>
        , escalate after <strong data-testid="setting-escalate-after-current">{fig(settings.data?.escalateAfter ?? '')}</strong>
        , review SLA <strong data-testid="setting-review-sla-current">{fig(settings.data?.reviewSla ?? '')}</strong>
        , entry date <strong data-testid="setting-entry-date-current">{fig(settings.data?.entryDate ?? '')}</strong>
        , pot <strong data-testid="setting-pot-current">{fig(settings.data?.pot ?? '')}</strong>
        , parent <strong data-testid="setting-parent-current">{fig(settings.data?.parent ?? '')}</strong>
        , fiscal year starts in month{' '}
        <strong data-testid="setting-fiscal-start-month-current">{fig(settings.data?.fiscalStartMonth ?? '')}</strong>
        , alert threshold <strong data-testid="setting-alert-threshold-current">{fig(settings.data?.alertThreshold ?? '')}</strong>
        {save.isError && <p data-testid="settings-error">{save.error.message}</p>}

